<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();function scalar(PDO $db,string $sql):float{$v=$db->query($sql)->fetchColumn();return (float)($v??0);} $k=[];$k['clients']=scalar($db,'SELECT COUNT(*) FROM clients');$k['projects']=scalar($db,'SELECT COUNT(*) FROM client_projects');$k['open_tickets']=scalar($db,"SELECT COUNT(*) FROM support_tickets WHERE status NOT IN ('resolved','closed')");$k['at_risk']=scalar($db,"SELECT COUNT(*) FROM client_success_profiles WHERE health IN ('at_risk','critical')");$k['open_tasks']=scalar($db,"SELECT COUNT(*) FROM project_tasks WHERE status IN ('todo','in_progress','blocked')");$k['sla_risks']=scalar($db,"SELECT COUNT(*) FROM support_tickets WHERE due_at IS NOT NULL AND due_at<NOW() AND status NOT IN ('resolved','closed')");?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Executive BI</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Executive BI & Operations</h1><div class="row g-3"><?php foreach($k as $name=>$value):?><div class="col-md-4"><div class="card"><div class="card-body"><div class="text-muted text-uppercase small"><?=htmlspecialchars(str_replace('_',' ',$name))?></div><div class="display-6"><?=number_format($value)?></div></div></div></div><?php endforeach;?></div><div class="mt-4"><a class="btn btn-dark" href="reports.php">Report Center</a> <a class="btn btn-outline-dark" href="automation.php">Automation</a> <a class="btn btn-outline-dark" href="bi-alerts.php">Alerts</a></div></main></body></html>